      unsupported: ['Unsupported file', 'This file type isn’t supported by this tool. Your file stayed on your device.', 'Choose another tool', 'help_center', 'var(--am)', 'Cancel'],
      oversize: ['File exceeds 500 MB', 'This file is over the 500 MB limit that applies to all tools.', 'Choose another file', 'straighten', 'var(--am)', 'Cancel'],
